COUNTROWS (
    FILTER (
        CROSSJOIN (
            ADDCOLUMNS (
                SUMMARIZE ( 'Machine Data', Machine[Machine Code], 'OEE Plant'[Plant Name] ),
                "@From_Date", CALCULATE ( MAX ( 'Machine Settings'[Machine_Data_Good_From_Date] ) ),
                "@To_Date", CALCULATE ( MAX ( 'Machine Settings'[Machine Data Good To Date] ) )
            ),
            VALUES ( 'Time'[Reporting Date] )
        ),
        'Time'[Reporting Date] >= [@From_Date]
            && (
                'Time'[Reporting Date] <= [@To_Date] || ISBLANK ( [@To_Date] )
            )
    )
) * 24

AVERAGEX (
    DISTINCT (
        SELECTCOLUMNS (
            'Machine',
            "Machine", Machine[Machine],
            "Actual Seconds per Cycle", [Actual Seconds Per Cycle]
        )
    ),
    [Actual Seconds Per Cycle]
)

